function ProjectGallery({project,compact=false}:{project:Project;compact?:boolean}){
 const[index,setIndex]=useState(0);const[portrait,setPortrait]=useState(false);const count=project.images.length;const current=project.images[index];
 function move(step:number){setIndex(i=>(i+step+count)%count)}
 if(!current)return <p className="notice">Project photographs coming soon.</p>;
 const photo=<img key={current.src+index} src={current.src} alt={current.alt} loading="lazy" onLoad={event=>setPortrait(event.currentTarget.naturalHeight>event.currentTarget.naturalWidth)} onError={event=>{event.currentTarget.hidden=true}}/>;
 return <div className={'project-gallery '+(compact?'compact':'full')} role="region" aria-roledescription="carousel" aria-label={project.title+' photo gallery'} tabIndex={0} onKeyDown={e=>{if(count>1&&(e.key==='ArrowLeft'||e.key==='ArrowRight')){e.preventDefault();move(e.key==='ArrowLeft'?-1:1)}}}>
 <div className={'gallery-stage '+(portrait?'portrait':'')}>
 {compact?<a className="gallery-photo-link" href={'/projects/'+project.slug} aria-label={'View project: '+project.title}>{photo}</a>:photo}
 <span className="gallery-placeholder">PROJECT PHOTO</span>
 {count>1&&<><button type="button" className="gallery-arrow previous" aria-label={'Previous photo of '+project.title} onClick={()=>move(-1)}><ArrowRight size={19}/></button><button type="button" className="gallery-arrow next" aria-label={'Next photo of '+project.title} onClick={()=>move(1)}><ArrowRight size={19}/></button></>}
 <span className="gallery-count" aria-live="polite" aria-atomic="true">{String(index+1).padStart(2,'0')} / {String(count).padStart(2,'0')}</span>
 </div>
 {!compact&&<div className="gallery-thumbnails" aria-label="Choose a photo">{project.images.map((img,i)=><button type="button" key={i} aria-label={'Show photo '+(i+1)} aria-pressed={index===i} className={index===i?'selected':''} onClick={()=>setIndex(i)}><img src={img.src} alt={img.alt} loading="lazy" onError={event=>{event.currentTarget.hidden=true}}/><span>{String(i+1).padStart(2,'0')}</span></button>)}</div>}
 </div>
}
function Projects(){const[filter,setFilter]=useState('All');return <><PageIntro label="Our projects" title="Spaces shaped around real needs." desc="Explore Fast Traders projects across government, banking and residential spaces."/><section className="section container"><p className="notice">Add each project photo to its own folder under public/images/projects/. See README.md for the folder names.</p><div className="filters">{['All','Government','Banking','Residential'].map(f=><button className={f===filter?'selected':''} aria-pressed={f===filter} onClick={()=>setFilter(f)} key={f}>{f}</button>)}</div><div className="project-grid">{PROJECTS.filter(p=>filter==='All'||p.category===filter).map(project=><article className="project-card" key={project.slug}><ProjectGallery project={project} compact/><span>{project.category} / {project.images.length} PHOTOS</span><h3><a href={'/projects/'+project.slug}>{project.title}</a></h3><a className="text-link" href={'/projects/'+project.slug}>View project <ArrowUpRight size={17}/></a></article>)}</div></section></>}
