function FAQ(){return <div className="faq">{[['How do I get a quotation?','Share your requirements through the inquiry form or WhatsApp. Site measurements and the agreed scope help determine an accurate quotation.'],['Can you take on smaller jobs?','Tell us what you need, whether it is paint work, flooring, furniture or a larger renovation. The team will confirm scope and scheduling.'],['How much will my renovation cost?','Pricing depends on site conditions, quantities, materials and finishes. A project-specific quotation is provided rather than a one-size-fits-all rate.'],['Can I share reference images?','Yes. Send your references and photos of the existing space on WhatsApp so the team can understand your preferences.']].map(([q,a])=><details key={q}><summary>{q}<Plus size={18}/></summary><p>{a}</p></details>)}</div>}
function Contact(){const[sent,setSent]=useState(false);const[msg,setMsg]=useState('');function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);setMsg(`Hello Fast Traders!\nName: ${f.get('name')}\nPhone: ${f.get('phone')}\nService: ${f.get('service')}\nLocation: ${f.get('location')}\nProject: ${f.get('message')}`);setSent(true)}return <><PageIntro label="Let’s talk" title="Your space. Your next chapter." desc="Tell us what you have in mind. A little detail now helps start a better conversation."/><section className="section container contact-grid"><aside><Eyebrow>GET IN TOUCH</Eyebrow><h2>Let’s make<br/>something better.</h2><a href={`tel:${COMPANY.phone.replaceAll(' ','')}`}><Phone/>{COMPANY.phone}</a><a href={'mailto:'+COMPANY.email}><Mail/>{COMPANY.email}</a><p><MapPin/>{COMPANY.address}</p><Button href={wa()}>Chat on WhatsApp</Button><p className="small-copy">Prefer to show us? Share photos of your existing space and references directly on WhatsApp.</p></aside><form onSubmit={submit}><h3>Tell us about your project</h3><div className="form-grid"><label>Your name<input name="name" required autoComplete="name" placeholder="Full name"/></label><label>Phone number<input name="phone" required type="tel" autoComplete="tel" placeholder="03XX XXXXXXX" pattern="[+0-9 ()-]{7,20}"/></label><label>Service<select name="service" required defaultValue=""><option value="" disabled>Select a service</option>{services.map(s=><option key={s[0]}>{s[1]}</option>)}</select></label><label>Project location<input name="location" required placeholder="Area / city"/></label></div><label>A little about your project<textarea name="message" rows={5} required placeholder="What would you like to renovate? Tell us about your space, timing and preferences."/></label><p className="small-copy">Your inquiry is prepared here, then sent by you through WhatsApp.</p><button className="button" type="submit">Prepare inquiry <ArrowUpRight size={18}/></button>{sent&&<div className="form-result" role="status"><Check/>Your inquiry is ready. <a href={wa(msg)} target="_blank" rel="noreferrer">Open WhatsApp to send <ArrowUpRight size={15}/></a></div>}</form></section><section className="section container faq-section"><h2>A few things<br/>you might be wondering.</h2><FAQ/></section></>}
function ServiceDetail({slug}:{slug:string}){const s=services.find(s=>s[0]===slug);if(!s)return <PageIntro label="Not found" title="Let’s find the right space." desc="Explore our services from the menu."/>;return <><PageIntro label={s[1]} title={s[1]} desc={s[3]} tagline={s[2]}/><section className="section container detail-grid"><Photo name={s[4]} alt={s[1]+' inspiration'}/><div><Eyebrow>PLANNED AROUND YOUR SPACE</Eyebrow><h2>The details,<br/>taken care of.</h2><p>We begin with your requirements and site conditions, then discuss the materials, dimensions and finish that suit your project.</p><ul className="scope-list">{s[5].split('|').map(x=><li key={x}><Check size={19}/>{x}</li>)}</ul><Button href={wa('Hello Fast Traders! I would like a quotation for '+s[1]+'.')}>Discuss this service</Button><p className="small-copy">Photograph shown for inspiration. Final scope and pricing are confirmed by quotation.</p></div></section><section className="section container"><div className="section-heading"><h2>From idea to installation.</h2></div><Process/></section></>}
export default function FastTraders({page='home'}:{page?:string}){useEffect(()=>{const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)e.target.animate([{opacity:0,transform:'translateY(28px)'},{opacity:1,transform:'translateY(0)'}],{duration:700,easing:'cubic-bezier(.2,.7,.3,1)',fill:'both'});observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));return()=>observer.disconnect()},[page]);return <><style>{CSS}</style><a className="skip-link" href="#main">Skip to content</a><Header page={page}/><main id="main">{page==='home'?<Home/>:page==='services'?<><PageIntro label="Our services" title="One team. Every possibility." desc="Fifteen specialist services for homes, offices and the spaces in between. Find the right starting point for your project."/><section className="section container"><ServiceGrid/></section></>:page.startsWith('services/')?<ServiceDetail slug={page.split('/')[1]}/>:page==='furniture'?<Furniture/>:page==='projects'?<Projects/>:page.startsWith('projects/')?<ProjectDetail slug={page.split('/')[1]}/>:page==='contact'?<Contact/>:page==='how-it-works'?<><PageIntro label="How it works" title="A better space starts with a plan." desc="From your first conversation to the finishing details, begin with a shared understanding of what your project needs."/><section className="section container"><Process/><div className="process-note"><Eyebrow>CLARITY BEFORE COMMITMENT</Eyebrow><h2>Know what goes into your quotation.</h2><p>Work descriptions, units, quantities, material specifications and payment terms help you understand the scope. Timelines and commercial terms are confirmed for each project.</p><Button>Start a conversation</Button></div><FAQ/></section></>:<><PageIntro label="About Fast Traders" title="Count on us. For every detail." desc="A Lahore-based business bringing renovation, interiors, furniture and technical work together for homes and offices."/><section className="section container detail-grid"><Photo name="office" alt="Workplace design inspiration"/><div><Eyebrow>FAST TRADERS</Eyebrow><h2>Practical thinking.<br/>Thoughtful spaces.</h2><p>A fresh coat of paint. A more useful kitchen. An office ready for the next chapter. Every project begins with understanding how you want your space to work.</p><p>Our services cover civil work, surfaces, woodwork, glass, electrical and networking, CCTV, blinds and furniture. Discuss one requirement or bring your complete renovation brief.</p><Button>Meet your next project</Button></div></section><section className="dark-section section"><div className="container"><Eyebrow>OUR APPROACH</Eyebrow><h2>Your priorities shape the plan.</h2><Process/></div></section></>}</main><Footer/></>}
